output_text:
[
  {
    "id": "get_cart_first",
    "text": "The shopper is obliged to obtain a shopping cart at some point during the trip.",
    "abstraction": {},
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "hasCart"
    }
  },
  {
    "id": "use_entrance_cart_station",
    "text": "The shopper is obliged to interact at the entrance cart location before continuing the shop.",
    "abstraction": {},
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": {
        "and": [
          "at(1,7)",
          "INTERACT"
        ]
      }
    }
  },
  {
    "id": "no_cart_in_item_cell",
    "text": "The shopper is prohibited from being at the item shelf location while holding a cart.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "at(3,1)",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "no_cart_in_narrow_aisle",
    "text": "The shopper is prohibited from taking a cart into the narrow aisle cells near the item.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          {
            "or": [
              "at(3,1)",
              "at(3,2)"
            ]
          }
        ]
      }
    }
  },
  {
    "id": "do_not_push_cart_north_from_parking",
    "text": "The shopper is prohibited from pushing a cart north from the cart-parking cell.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "at(3,3)",
          "hasCart",
          "N"
        ]
      }
    }
  },
  {
    "id": "park_cart_at_aisle_entrance",
    "text": "If the shopper interacts at the aisle entrance while holding a cart, they are obliged to leave the cart there.",
    "abstraction": {},
    "norm": {
      "type": "obligation",
      "trigger": {
        "and": [
          "at(3,3)",
          "hasCart",
          "INTERACT"
        ]
      },
      "discharge": {
        "and": [
          "at(3,3)",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "return_to_cart_after_item",
    "text": "After interacting at the item shelf, the shopper is obliged to return to the cart-parking location and interact there.",
    "abstraction": {},
    "norm": {
      "type": "obligation",
      "trigger": {
        "and": [
          "at(3,1)",
          "INTERACT"
        ]
      },
      "discharge": {
        "and": [
          "at(3,3)",
          "INTERACT"
        ]
      }
    }
  },
  {
    "id": "exit_with_cart",
    "text": "The shopper is prohibited from exiting the supermarket without a cart.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  }
]
